questionvariables.text:
/* Baseline segments along AD */
d1: 5 + rand(3); 
d2: 6 + rand(4); 
d3: 4 + rand(3); 
AD: d1 + d2 + d3;

/* Offsets */
hL: 4 + rand(3); 
hR: 5 + rand(3); 

/* Calculations */
area_left: float((1/2) * AD * hL);
area_right: float((1/2) * AD * hR);
ta: float(area_left + area_right);

/* Mistakes for PRT */
m1: float((AD * hL) + (AD * hR)); /* Forgot the 1/2 factor */
